import random

secret = random.randint(1, 10)
guess = 0

while guess != secret:
    guess = int(input("Guess my number (1-10): "))

    if guess < secret:
        print("Too low!")
    elif guess > secret:
        print("Too high!")

print("You got it! The number was", secret)

